-- ============================================================
-- AquaAlerta: troca os dados fictícios do seed por dados reais
--
-- 1. Guarda uma cópia do seed no schema arquivo_seed (fora da API).
-- 2. Apaga alertas, eventos e regiões fictícios.
-- 3. Estações: só as que têm cotas oficiais do SGB (Serviço Geológico
--    do Brasil), com o código da telemetria da ANA.
-- 4. Regiões: os municípios dessas estações, com o limite oficial do
--    IBGE (malha municipal, qualidade intermediária).
-- 5. Alertas: gerados sozinhos a partir das leituras da ANA sempre que
--    o rio passa da cota de alerta, e encerrados quando volta a baixar.
-- Pode rodar mais de uma vez.
-- ============================================================

-- 1. Cópia do seed ------------------------------------------------
CREATE SCHEMA IF NOT EXISTS arquivo_seed;
REVOKE ALL ON SCHEMA arquivo_seed FROM anon, authenticated;
DO $$
BEGIN
    IF to_regclass('arquivo_seed.alerts') IS NULL THEN
        CREATE TABLE arquivo_seed.alert_deliveries AS SELECT * FROM public.alert_deliveries;
        CREATE TABLE arquivo_seed.alerts           AS SELECT * FROM public.alerts;
        CREATE TABLE arquivo_seed.flood_events     AS SELECT * FROM public.flood_events;
        CREATE TABLE arquivo_seed.monitored_regions AS SELECT * FROM public.monitored_regions;
        CREATE TABLE arquivo_seed.user_monitored_regions AS SELECT * FROM public.user_monitored_regions;
        CREATE TABLE arquivo_seed.hydro_stations   AS SELECT * FROM public.hydro_stations;
    END IF;
END $$;

-- 2. Remove o que é fictício ---------------------------------------
DELETE FROM public.alert_deliveries;
DELETE FROM public.alerts            WHERE coalesce(metadata->>'origem','') <> 'telemetria-ana';
DELETE FROM public.flood_events      WHERE coalesce(processing_metadata->>'origem','') <> 'telemetria-ana';
DELETE FROM public.monitored_regions WHERE coalesce(monitoring_config->>'origem','') <> 'ibge';

-- 3. Estações com cotas oficiais -----------------------------------
--    Cotas do SGB: alerta, inundação (primeiras casas atingidas) e
--    inundação severa. A coluna normal_level_m deixa de ser usada.
ALTER TABLE public.hydro_stations ALTER COLUMN normal_level_m    DROP NOT NULL;
ALTER TABLE public.hydro_stations ALTER COLUMN emergency_level_m DROP NOT NULL;

DROP TABLE IF EXISTS estacoes_reais;
CREATE TEMP TABLE estacoes_reais (
    ana_code text, name text, river text, lat float8, lng float8,
    alerta numeric, inundacao numeric, severa numeric,
    ibge text, municipio text, uf text, fonte text
);
