    ('13600002','Rio Branco','Rio Acre',-9.975,-67.8008,13.50,14.00,NULL,'1200401','Rio Branco','AC','SGB, SAH Acre');

-- Estações sem cotas oficiais publicadas (Tefé, Santarém, Óbidos) saem.
DELETE FROM public.hydro_readings
 WHERE station_id IN (SELECT id FROM public.hydro_stations WHERE ana_code NOT IN (SELECT ana_code FROM estacoes_reais));
DELETE FROM public.hydro_stations WHERE ana_code NOT IN (SELECT ana_code FROM estacoes_reais);

INSERT INTO public.hydro_stations
    (ana_code, name, river, location, normal_level_m, alert_level_m, flood_level_m, emergency_level_m, is_active, metadata)
SELECT ana_code, name, river, ST_SetSRID(ST_MakePoint(lng, lat), 4326),
       NULL, alerta, inundacao, severa, true,
       jsonb_build_object('fonte_cotas', fonte, 'municipio_ibge', ibge)
FROM estacoes_reais
ON CONFLICT (ana_code) DO UPDATE SET
    name = EXCLUDED.name, river = EXCLUDED.river, location = EXCLUDED.location,
    normal_level_m = NULL, alert_level_m = EXCLUDED.alert_level_m,
    flood_level_m = EXCLUDED.flood_level_m, emergency_level_m = EXCLUDED.emergency_level_m,
    is_active = true, metadata = EXCLUDED.metadata;

-- 4. Municípios com limite do IBGE ---------------------------------
DROP TABLE IF EXISTS malhas_ibge;
CREATE TEMP TABLE malhas_ibge (ibge text, geojson text);
