INSERT INTO public.monitored_regions
    (name, description, geometry, centroid, area_km2, state_code, municipality, is_public, monitoring_config)
SELECT e.municipio,
       'Município de ' || e.municipio || '. Nível do ' || e.river || ' pela estação ' || e.ana_code || ' da ANA.',
       ST_SetSRID(ST_GeomFromGeoJSON(m.geojson), 4326),
       ST_SetSRID(ST_MakePoint(e.lng, e.lat), 4326),
       round((ST_Area(ST_SetSRID(ST_GeomFromGeoJSON(m.geojson), 4326)::geography) / 1e6)::numeric, 1),
       e.uf, e.municipio, true,
       jsonb_build_object('origem', 'ibge', 'municipio_ibge', e.ibge, 'estacao_ana', e.ana_code)
FROM estacoes_reais e
JOIN malhas_ibge m ON m.ibge = e.ibge
WHERE NOT EXISTS (
    SELECT 1 FROM public.monitored_regions r WHERE r.monitoring_config->>'municipio_ibge' = e.ibge
);

-- O centro da região é a própria estação (o app liga região e estação
-- pela proximidade).
CREATE OR REPLACE VIEW public.v_regioes_mapa
WITH (security_invoker = on) AS
SELECT
    mr.id,
    mr.name,
    mr.state_code,
    mr.municipality,
    mr.area_km2,
    ST_AsGeoJSON(mr.geometry)::json                          AS geojson,
    ST_Y(COALESCE(mr.centroid, ST_Centroid(mr.geometry)))    AS center_lat,
    ST_X(COALESCE(mr.centroid, ST_Centroid(mr.geometry)))    AS center_lng
FROM public.monitored_regions mr
WHERE mr.is_public = true;

-- Nível de 24 h atrás, para mostrar se o rio sobe ou desce.
CREATE OR REPLACE VIEW public.v_estacoes_nivel
WITH (security_invoker = on) AS
SELECT
    hs.id,
    hs.ana_code,
    hs.name,
    hs.river,
    ST_Y(hs.location)                        AS lat,
    ST_X(hs.location)                        AS lng,
    hs.normal_level_m,
    hs.alert_level_m,
    hs.flood_level_m,
    hs.emergency_level_m,
    ult.water_level_m,
    ult.recorded_at,
    ant.water_level_m                        AS level_24h_m,
    ant.recorded_at                          AS recorded_24h_at
FROM public.hydro_stations hs
LEFT JOIN LATERAL (
    SELECT hr.water_level_m, hr.recorded_at
    FROM public.hydro_readings hr
    WHERE hr.station_id = hs.id AND hr.water_level_m IS NOT NULL
    ORDER BY hr.recorded_at DESC
    LIMIT 1
) ult ON true
LEFT JOIN LATERAL (
    SELECT hr.water_level_m, hr.recorded_at
    FROM public.hydro_readings hr
    WHERE hr.station_id = hs.id AND hr.water_level_m IS NOT NULL
      AND hr.recorded_at BETWEEN ult.recorded_at - interval '27 hours' AND ult.recorded_at - interval '21 hours'
    ORDER BY abs(extract(epoch FROM hr.recorded_at - (ult.recorded_at - interval '24 hours')))
    LIMIT 1
) ant ON true
WHERE hs.is_active = true;

GRANT SELECT ON public.v_regioes_mapa, public.v_estacoes_nivel TO anon, authenticated;

-- 5. Alertas automáticos -------------------------------------------
--    Severidade (a mesma regra do app):
--      abaixo da cota de alerta           -> LOW (sem alerta)
--      da cota de alerta                   -> MEDIUM
--      da cota de inundação                -> HIGH
--      da cota de inundação severa         -> CRITICAL
-- Metros no formato brasileiro (27,51).
CREATE OR REPLACE FUNCTION public.metros_br(v numeric)
RETURNS text LANGUAGE sql IMMUTABLE
AS $$ SELECT replace(to_char(v, 'FM9990.00'), '.', ',') $$;

CREATE OR REPLACE FUNCTION public.ana_atualizar_alertas()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
    x        record;
    sev      text;
    titulo   text;
    texto    text;
    evento   uuid;
    mudancas integer := 0;
BEGIN
    FOR x IN
        SELECT r.id AS region_id, r.name AS municipio, s.ana_code, s.river,
               s.alert_level_m, s.flood_level_m, s.emergency_level_m,
               ult.water_level_m AS nivel, ult.recorded_at,
               ST_Y(COALESCE(r.centroid, ST_Centroid(r.geometry))) AS lat,
               ST_X(COALESCE(r.centroid, ST_Centroid(r.geometry))) AS lng,
               a.id AS alerta_id, a.severity AS sev_atual, a.flood_event_id
        FROM public.monitored_regions r
        JOIN public.hydro_stations s ON s.ana_code = r.monitoring_config->>'estacao_ana' AND s.is_active
        JOIN LATERAL (
            SELECT hr.water_level_m, hr.recorded_at FROM public.hydro_readings hr
            WHERE hr.station_id = s.id AND hr.water_level_m IS NOT NULL
            ORDER BY hr.recorded_at DESC LIMIT 1
        ) ult ON ult.recorded_at > now() - interval '48 hours'
        LEFT JOIN public.alerts a ON a.region_id = r.id AND a.status = 'ACTIVE'
        WHERE s.alert_level_m IS NOT NULL
    LOOP
        sev := CASE
            WHEN x.emergency_level_m IS NOT NULL AND x.nivel >= x.emergency_level_m THEN 'CRITICAL'
            WHEN x.flood_level_m IS NOT NULL AND x.nivel >= x.flood_level_m THEN 'HIGH'
            WHEN x.nivel >= x.alert_level_m THEN 'MEDIUM'
            ELSE 'LOW' END;

        IF sev = 'LOW' THEN
            IF x.alerta_id IS NOT NULL THEN
                UPDATE public.alerts
                   SET status = 'RESOLVED', resolved_at = now(), valid_until = now(),
                       body = body || ' Encerrado: o rio voltou para baixo da cota de alerta ('
                              || public.metros_br(x.nivel) || ' m em ' || to_char(x.recorded_at AT TIME ZONE 'America/Manaus', 'DD/MM HH24:MI') || ').'
                 WHERE id = x.alerta_id;
                mudancas := mudancas + 1;
            END IF;
            CONTINUE;
        END IF;

        IF x.sev_atual = sev THEN CONTINUE; END IF;

        titulo := x.river || ' ' || CASE sev
            WHEN 'CRITICAL' THEN 'acima da cota de inundação severa'
            WHEN 'HIGH'     THEN 'acima da cota de inundação'
            ELSE                 'acima da cota de alerta' END || ' em ' || x.municipio;
        texto := 'O ' || x.river || ' marcou ' || public.metros_br(x.nivel) || ' m na estação '
              || x.ana_code || ' da ANA (' || to_char(x.recorded_at AT TIME ZONE 'America/Manaus', 'DD/MM HH24:MI')
              || '). Cotas do SGB: alerta ' || public.metros_br(x.alert_level_m) || ' m'
              || coalesce(', inundação ' || public.metros_br(x.flood_level_m) || ' m', '')
              || coalesce(', inundação severa ' || public.metros_br(x.emergency_level_m) || ' m', '') || '.';

        IF x.alerta_id IS NULL THEN
            INSERT INTO public.flood_events
                (region_id, detected_at, severity, center_lat, center_lng, processing_metadata)
            VALUES (x.region_id, x.recorded_at, sev, x.lat, x.lng,
                    jsonb_build_object('origem', 'telemetria-ana', 'estacao_ana', x.ana_code, 'nivel_m', x.nivel))
            RETURNING id INTO evento;
            INSERT INTO public.alerts
                (flood_event_id, region_id, title, body, severity, status, valid_from, issued_at, metadata)
            VALUES (evento, x.region_id, titulo, texto, sev, 'ACTIVE', x.recorded_at, now(),
                    jsonb_build_object('origem', 'telemetria-ana', 'estacao_ana', x.ana_code, 'nivel_m', x.nivel));
        ELSE
            UPDATE public.alerts
               SET severity = sev, title = titulo, body = texto,
                   metadata = metadata || jsonb_build_object('nivel_m', x.nivel)
             WHERE id = x.alerta_id;
            UPDATE public.flood_events SET severity = sev WHERE id = x.flood_event_id;
        END IF;
        mudancas := mudancas + 1;
    END LOOP;
    RETURN mudancas;
END $$;
REVOKE ALL ON FUNCTION public.ana_atualizar_alertas() FROM PUBLIC, anon, authenticated;

-- Roda logo depois de cada processamento das leituras.
SELECT cron.schedule('ana-atualizar-alertas', '7,37 * * * *', 'SELECT public.ana_atualizar_alertas()');

-- Busca já as leituras das estações novas (gravadas no próximo :05 ou :35).
SELECT public.ana_solicitar_leituras() AS pedidos_enviados,
       (SELECT count(*) FROM public.hydro_stations)    AS estacoes,
       (SELECT count(*) FROM public.monitored_regions) AS regioes,
       (SELECT count(*) FROM public.alerts)            AS alertas;
